/**
 * Deterministic PRNG kernel.
 *
 * All randomness in STARWEFT rule code flows through named streams created by
 * `rngStream(seed, ...path)`. The same (seed, path) always yields the same
 * sequence, which makes universe generation, combat resolution, and every test
 * exactly reproducible. `Math.random` / `Date.now` are banned in rule code
 * (enforced by tools/check-determinism.mjs).
 *
 * Algorithm: xoshiro128** (public-domain algorithm by Blackman & Vigna),
 * seeded via FNV-1a path hashing expanded with splitmix32.
 */

/** FNV-1a 32-bit hash of a string. */
export function fnv1a32(str: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** splitmix32 stepper — expands one 32-bit seed into a stream of well-mixed words. */
function splitmix32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x9e3779b9) >>> 0;
    let z = s;
    z = Math.imul(z ^ (z >>> 16), 0x21f0aaad);
    z = Math.imul(z ^ (z >>> 15), 0x735a2d97);
    return (z ^ (z >>> 15)) >>> 0;
  };
}

function rotl(x: number, k: number): number {
  return ((x << k) | (x >>> (32 - k))) >>> 0;
}

/** Deterministic xoshiro128** PRNG. Construct via {@link rngStream}. */
export class Rng {
  private s0: number;
  private s1: number;
  private s2: number;
  private s3: number;

  constructor(seed32: number) {
    const mix = splitmix32(seed32);
    this.s0 = mix();
    this.s1 = mix();
    this.s2 = mix();
    this.s3 = mix();
    // xoshiro state must never be all-zero; splitmix32 output makes this
    // astronomically unlikely, but guard anyway.
    if ((this.s0 | this.s1 | this.s2 | this.s3) === 0) this.s3 = 1;
  }

  /** Next unsigned 32-bit integer. */
  nextU32(): number {
    const result = (Math.imul(rotl(Math.imul(this.s1, 5) >>> 0, 7), 9) >>> 0) >>> 0;
    const t = (this.s1 << 9) >>> 0;
    this.s2 = (this.s2 ^ this.s0) >>> 0;
    this.s3 = (this.s3 ^ this.s1) >>> 0;
    this.s1 = (this.s1 ^ this.s2) >>> 0;
    this.s0 = (this.s0 ^ this.s3) >>> 0;
    this.s2 = (this.s2 ^ t) >>> 0;
    this.s3 = rotl(this.s3, 11);
    return result;
  }

  /** Uniform float in [0, 1). */
  float(): number {
    return this.nextU32() / 4294967296;
  }

  /** Uniform integer in [minInclusive, maxExclusive). */
  int(minInclusive: number, maxExclusive: number): number {
    if (!Number.isInteger(minInclusive) || !Number.isInteger(maxExclusive)) {
      throw new Error('Rng.int bounds must be integers');
    }
    const span = maxExclusive - minInclusive;
    if (span <= 0) throw new Error(`Rng.int empty range [${minInclusive}, ${maxExclusive})`);
    return minInclusive + Math.floor(this.float() * span);
  }

  /** Uniform float in [min, max). */
  range(min: number, max: number): number {
    return min + this.float() * (max - min);
  }

  /** Bernoulli trial with probability p. */
  chance(p: number): boolean {
    return this.float() < p;
  }

  /** Uniform pick from a non-empty array. */
  pick<T>(arr: readonly T[]): T {
    if (arr.length === 0) throw new Error('Rng.pick from empty array');
    const v = arr[this.int(0, arr.length)];
    return v as T;
  }

  /** Weighted pick; weights must be non-negative and sum > 0. */
  weightedPick<T>(entries: ReadonlyArray<readonly [T, number]>): T {
    let total = 0;
    for (const [, w] of entries) {
      if (w < 0) throw new Error('Rng.weightedPick negative weight');
      total += w;
    }
    if (total <= 0) throw new Error('Rng.weightedPick zero total weight');
    let roll = this.float() * total;
    for (const [value, w] of entries) {
      roll -= w;
      if (roll < 0) return value;
    }
    // Floating-point tail: return the last entry.
    const last = entries[entries.length - 1];
    if (last === undefined) throw new Error('Rng.weightedPick empty entries');
    return last[0];
  }

  /** Fisher–Yates shuffle (returns a new array). */
  shuffle<T>(arr: readonly T[]): T[] {
    const out = arr.slice();
    for (let i = out.length - 1; i > 0; i--) {
      const j = this.int(0, i + 1);
      const a = out[i] as T;
      out[i] = out[j] as T;
      out[j] = a;
    }
    return out;
  }

  /** Approximately normal sample (Irwin–Hall of 6, cheap and deterministic). */
  normal(mean: number, sd: number): number {
    let acc = 0;
    for (let i = 0; i < 6; i++) acc += this.float();
    return mean + ((acc - 3) / Math.sqrt(0.5)) * sd * 0.7071067811865476;
  }
}

/**
 * Create a named deterministic stream. Streams with different paths are
 * statistically independent; the same (seed, path) is always identical.
 */
export function rngStream(seed: number | string, ...path: ReadonlyArray<string | number>): Rng {
  const key = `${seed}�${path.join('�')}`;
  return new Rng(fnv1a32(key));
}
